/**
     * Read a specific number of bytes from the stream.
     *
     * @param numberOfBytes The number of bytes to read.
     * @return The byte buffer.
     * @throws IOException If there is an error while reading.
     */
public byte[] read(int numberOfBytes) throws IOException {
        byte[] data = new byte[numberOfBytes];
        int amountRead = 0;
        int totalAmountRead = 0;
        // read at most numberOfBytes bytes from the stream.
        while (totalAmountRead < numberOfBytes
                && (amountRead = read(data, totalAmountRead, numberOfBytes - totalAmountRead)) != -1) {
            totalAmountRead += amountRead;
        }
        if (totalAmountRead == numberOfBytes) {
            return data;
        } else {
            throw new IOException("Unexpected end of TTF stream reached");
        }
    }

/**
     * 解析cmap
     *
     * @param cmapOffset cmap开始偏移量
     * @param data       随机访问流
     * @return cmap子表数组
     * @throws IOException IOE
     */
public CmapSubtable[] readCMap(long cmapOffset, TTFDataStream data) throws IOException {
        // 定位到cmap
        data.seek(cmapOffset);
        int version = data.readUnsignedShort();
        int numberOfTables = data.readUnsignedShort();
        CmapSubtable[] cmaps = new CmapSubtable[numberOfTables];
        // 依次子表信息数组
        for (int i = 0; i < numberOfTables; i++) {
            cmaps[i] = new CmapSubtable().initData(data);
        }
        for (int i = 0; i < numberOfTables; i++) {
            // 依次解析子表
            cmaps[i].initSubtable(cmapOffset, this.numGlyphs, data);
        }
        return cmaps;
    }

/**
     * 判断是否是Type1 字体
     *
     * @param raw 字体内容
     * @return true - type1 字体；false - 非 type1
     */
public static boolean isType1(byte[] raw) {
        if (raw == null || raw.length <= 2) {
            return false;
        }
        if ((raw[0] & 0xff) == 0x80 && (raw[1] & 0xff) == 0x01) {
            return true;
        }
        if (raw[0] == '%' && raw[1] == '!') {
            return true;
        }
        return false;
    }

